import json
G=[[0]*26 for _ in range(16)]
# 3x3 macro pattern from the key, rotated clockwise; each macro cell is 4x4.
macro=[[3,0,0],[0,4,4],[2,2,0]]
for br,row in enumerate(macro):
    for bc,color in enumerate(row):
        if color:
            for r in range(3+4*br, 7+4*br):
                for c in range(2+4*bc, 6+4*bc):
                    G[r][c]=color
# Unchanged key/marker object.
for r,c,v in [(6,22,4),(7,22,4),(7,23,2),(8,21,3),(8,23,2)]: G[r][c]=v
assert len(G)==16 and all(len(row)==26 for row in G)
print(json.dumps({'action':'submit','grid':G},separators=(',',':')))
